=over 4

=item * C<< $msg->start_time() >> / C<< $msg->start_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The scheduled start time for the maintenance.

=back

=head2 Google::Cloud::Alloydb::V1::Resources::Cluster

A cluster is a collection of regional AlloyDB resources. It can include a
primary instance and one or more read pool instances.
All cluster resources share a storage layer, which scales as needed.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->backup_source() >> / C<< $msg->backup_source($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::BackupSource>)

Output only. Cluster created from backup.

=item * C<< $msg->migration_source() >> / C<< $msg->migration_source($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::MigrationSource>)

Output only. Cluster created via DMS migration.

=item * C<< $msg->cloudsql_backup_run_source() >> / C<< $msg->cloudsql_backup_run_source($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::CsqlResources::CloudSQLBackupRunSource>)

Output only. Cluster created from CloudSQL snapshot.

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. The name of the cluster resource with the format:
 * projects/{project}/locations/{region}/clusters/{cluster_id}
where the cluster ID segment should satisfy the regex expression
`[a-z0-9-]+`. For more details see https://google.aip.dev/122.
The prefix of the cluster resource name is the name of the parent resource:
 * projects/{project}/locations/{region}

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

User-settable and human-readable display name for the Cluster.

=item * C<< $msg->uid() >> / C<< $msg->uid($value) >>

Type: C<String>

Output only. The system-generated UID of the resource. The UID is assigned
when the resource is created, and it is retained until it is deleted.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Create time stamp

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Update time stamp

=item * C<< $msg->delete_time() >> / C<< $msg->delete_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Delete time stamp

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Cluster::LabelsEntry>)

Labels as key value pairs

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::Cluster::State>)

Output only. The current serving state of the cluster.

=item * C<< $msg->cluster_type() >> / C<< $msg->cluster_type($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::Cluster::ClusterType>)

Output only. The type of the cluster. This is an output-only field and it's
populated at the Cluster creation time or the Cluster promotion
time. The cluster type is determined by which RPC was used to create
the cluster (i.e. `CreateCluster` vs. `CreateSecondaryCluster`

=item * C<< $msg->database_version() >> / C<< $msg->database_version($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::DatabaseVersion>)

Optional. The database engine major version. This is an optional field and
it is populated at the Cluster creation time. If a database version is not
supplied at cluster creation time, then a default database version will
be used.

=item * C<< $msg->network_config() >> / C<< $msg->network_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Cluster::NetworkConfig>)

=item * C<< $msg->network() >> / C<< $msg->network($value) >>

Type: C<String>

Required. The resource link for the VPC network in which cluster resources
are created and from which they are accessible via Private IP. The network
must belong to the same project as the cluster. It is specified in the
form: `projects/{project}/global/networks/{network_id}`. This is required
to create a cluster. Deprecated, use network_config.network instead.

=item * C<< $msg->etag() >> / C<< $msg->etag($value) >>

Type: C<String>

For Resource freshness validation (https://google.aip.dev/154)

=item * C<< $msg->annotations() >> / C<< $msg->annotations($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Cluster::AnnotationsEntry>)

Annotations to allow client tools to store small amount of arbitrary data.
This is distinct from labels.
https://google.aip.dev/128

=item * C<< $msg->reconciling() >> / C<< $msg->reconciling($value) >>

Type: C<Bool>

Output only. Reconciling (https://google.aip.dev/128#reconciliation).
Set to true if the current state of Cluster does not match the user's
intended state, and the service is actively updating the resource to
reconcile them. This can happen due to user-triggered updates or
system actions like failover or maintenance.

=item * C<< $msg->initial_user() >> / C<< $msg->initial_user($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::UserPassword>)

Input only. Initial user to setup during cluster creation.
If used in `RestoreCluster` this is ignored.

=item * C<< $msg->automated_backup_policy() >> / C<< $msg->automated_backup_policy($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::AutomatedBackupPolicy>)

The automated backup policy for this cluster.

If no policy is provided then the default policy will be used. If backups
are supported for the cluster, the default policy takes one backup a day,
has a backup window of 1 hour, and retains backups for 14 days.
For more information on the defaults, consult the
documentation for the message type.

=item * C<< $msg->ssl_config() >> / C<< $msg->ssl_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::SslConfig>)

SSL configuration for this AlloyDB cluster.

=item * C<< $msg->encryption_config() >> / C<< $msg->encryption_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::EncryptionConfig>)

Optional. The encryption config can be specified to encrypt the data disks
and other persistent data resources of a cluster with a
customer-managed encryption key (CMEK). When this field is not
specified, the cluster will then use default encryption scheme to
protect the user data.

=item * C<< $msg->encryption_info() >> / C<< $msg->encryption_info($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::EncryptionInfo>)

Output only. The encryption information for the cluster.

=item * C<< $msg->continuous_backup_config() >> / C<< $msg->continuous_backup_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::ContinuousBackupConfig>)

Optional. Continuous backup configuration for this cluster.

=item * C<< $msg->continuous_backup_info() >> / C<< $msg->continuous_backup_info($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::ContinuousBackupInfo>)

Output only. Continuous backup properties for this cluster.

=item * C<< $msg->secondary_config() >> / C<< $msg->secondary_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Cluster::SecondaryConfig>)

Cross Region replication config specific to SECONDARY cluster.

=item * C<< $msg->primary_config() >> / C<< $msg->primary_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Cluster::PrimaryConfig>)

Output only. Cross Region replication config specific to PRIMARY cluster.

=item * C<< $msg->satisfies_pzs() >> / C<< $msg->satisfies_pzs($value) >>

Type: C<Bool>

Output only. Reserved for future use.

=item * C<< $msg->psc_config() >> / C<< $msg->psc_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Cluster::PscConfig>)

Optional. The configuration for Private Service Connect (PSC) for the
cluster.

=item * C<< $msg->maintenance_update_policy() >> / C<< $msg->maintenance_update_policy($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::MaintenanceUpdatePolicy>)

Optional. The maintenance update policy determines when to allow or deny
updates.

=item * C<< $msg->maintenance_schedule() >> / C<< $msg->maintenance_schedule($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::MaintenanceSchedule>)

Output only. The maintenance schedule for the cluster, generated for a
specific rollout if a maintenance window is set.

=item * C<< $msg->subscription_type() >> / C<< $msg->subscription_type($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::SubscriptionType>)

Optional. Subscription type of the cluster.

=item * C<< $msg->trial_metadata() >> / C<< $msg->trial_metadata($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Cluster::TrialMetadata>)

Output only. Metadata for free trial clusters

=item * C<< $msg->tags() >> / C<< $msg->tags($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Cluster::TagsEntry>)

