=head2 Google::Cloud::Alloydb::V1::Resources::ConnectionInfo

ConnectionInfo singleton resource.
https://google.aip.dev/156

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

The name of the ConnectionInfo singleton resource, e.g.:
projects/{project}/locations/{location}/clusters/*/instances/*/connectionInfo
This field currently has no semantic meaning.

=item * C<< $msg->ip_address() >> / C<< $msg->ip_address($value) >>

Type: C<String>

Output only. The private network IP address for the Instance. This is the
default IP for the instance and is always created (even if enable_public_ip
is set). This is the connection endpoint for an end-user application.

=item * C<< $msg->public_ip_address() >> / C<< $msg->public_ip_address($value) >>

Type: C<String>

Output only. The public IP addresses for the Instance. This is available
ONLY when enable_public_ip is set. This is the connection endpoint for an
end-user application.

=item * C<< $msg->instance_uid() >> / C<< $msg->instance_uid($value) >>

Type: C<String>

Output only. The unique ID of the Instance.

=back

=head2 Google::Cloud::Alloydb::V1::Resources::Backup

Message describing Backup object

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. The name of the backup resource with the format:
 * projects/{project}/locations/{region}/backups/{backup_id}
where the cluster and backup ID segments should satisfy the regex
expression `[a-z]([a-z0-9-]{0,61}[a-z0-9])?`, e.g. 1-63 characters of
lowercase letters, numbers, and dashes, starting with a letter, and ending
with a letter or number. For more details see https://google.aip.dev/122.
The prefix of the backup resource name is the name of the parent
resource:
 * projects/{project}/locations/{region}

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

User-settable and human-readable display name for the Backup.

=item * C<< $msg->uid() >> / C<< $msg->uid($value) >>

Type: C<String>

Output only. The system-generated UID of the resource. The UID is assigned
when the resource is created, and it is retained until it is deleted.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Create time stamp

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Update time stamp

Users should not infer any meaning from this field. Its value is generally
unrelated to the timing of the backup creation operation.

=item * C<< $msg->delete_time() >> / C<< $msg->delete_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Delete time stamp

=item * C<< $msg->create_completion_time() >> / C<< $msg->create_completion_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Timestamp when the resource finished being created.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Backup::LabelsEntry>)

Labels as key value pairs

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::Backup::State>)

Output only. The current state of the backup.

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::Backup::Type>)

The backup type, which suggests the trigger for the backup.

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

User-provided description of the backup.

=item * C<< $msg->cluster_uid() >> / C<< $msg->cluster_uid($value) >>

Type: C<String>

Output only. The system-generated UID of the cluster which was used to
create this resource.

=item * C<< $msg->cluster_name() >> / C<< $msg->cluster_name($value) >>

Type: C<String>

Required. The full resource name of the backup source cluster
(e.g., projects/{project}/locations/{region}/clusters/{cluster_id}).

=item * C<< $msg->reconciling() >> / C<< $msg->reconciling($value) >>

Type: C<Bool>

Output only. Reconciling (https://google.aip.dev/128#reconciliation), if
true, indicates that the service is actively updating the resource. This
can happen due to user-triggered updates or system actions like failover or
maintenance.

=item * C<< $msg->encryption_config() >> / C<< $msg->encryption_config($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::EncryptionConfig>)

Optional. The encryption config can be specified to encrypt the
backup with a customer-managed encryption key (CMEK). When this field is
not specified, the backup will then use default encryption scheme to
protect the user data.

=item * C<< $msg->encryption_info() >> / C<< $msg->encryption_info($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::EncryptionInfo>)

Output only. The encryption information for the backup.

=item * C<< $msg->etag() >> / C<< $msg->etag($value) >>

Type: C<String>

For Resource freshness validation (https://google.aip.dev/154)

=item * C<< $msg->annotations() >> / C<< $msg->annotations($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Backup::AnnotationsEntry>)

Annotations to allow client tools to store small amount of arbitrary data.
This is distinct from labels.
https://google.aip.dev/128

=item * C<< $msg->size_bytes() >> / C<< $msg->size_bytes($value) >>

Type: C<Int64>

Output only. The size of the backup in bytes.

=item * C<< $msg->expiry_time() >> / C<< $msg->expiry_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time at which after the backup is eligible to be garbage
collected. It is the duration specified by the backup's retention policy,
added to the backup's create_time.

=item * C<< $msg->expiry_quantity() >> / C<< $msg->expiry_quantity($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Backup::QuantityBasedExpiry>)

Output only. The QuantityBasedExpiry of the backup, specified by the
backup's retention policy. Once the expiry quantity is over retention, the
backup is eligible to be garbage collected.

=item * C<< $msg->satisfies_pzs() >> / C<< $msg->satisfies_pzs($value) >>

Type: C<Bool>

Output only. Reserved for future use.

=item * C<< $msg->database_version() >> / C<< $msg->database_version($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::DatabaseVersion>)

Output only. The database engine major version of the cluster this backup
was created from. Any restored cluster created from this backup will have
the same database version.

=item * C<< $msg->tags() >> / C<< $msg->tags($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::Backup::TagsEntry>)

Optional. Input only. Immutable. Tag keys/values directly bound to this
resource. For example:
```
"123/environment": "production",
"123/costCenter": "marketing"
```

=back

=head3 Enum: Backup::State

=over 4

=item * C<STATE_UNSPECIFIED> => C<0>

=item * C<READY> => C<1>

=item * C<CREATING> => C<2>

=item * C<FAILED> => C<3>

=item * C<DELETING> => C<4>

=back

=head3 Enum: Backup::Type

=over 4

=item * C<TYPE_UNSPECIFIED> => C<0>

=item * C<ON_DEMAND> => C<1>

=item * C<AUTOMATED> => C<2>

=item * C<CONTINUOUS> => C<3>

=back

=head2 Google::Cloud::Alloydb::V1::Resources::SupportedDatabaseFlag

SupportedDatabaseFlag gives general information about a database flag,
like type and allowed values. This is a static value that is defined
on the server side, and it cannot be modified by callers.
To set the Database flags on a particular Instance, a caller should modify
the Instance.database_flags field.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->string_restrictions() >> / C<< $msg->string_restrictions($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::SupportedDatabaseFlag::StringRestrictions>)

Restriction on STRING type value.

=item * C<< $msg->integer_restrictions() >> / C<< $msg->integer_restrictions($value) >>

Type: C<Message> (L<Google::Cloud::Alloydb::V1::Resources::SupportedDatabaseFlag::IntegerRestrictions>)

Restriction on INTEGER type value.

=item * C<< $msg->recommended_string_value() >> / C<< $msg->recommended_string_value($value) >>

Type: C<String>

The recommended value for a STRING flag.

=item * C<< $msg->recommended_integer_value() >> / C<< $msg->recommended_integer_value($value) >>

Type: C<Message> (L<Google::Protobuf::Wrappers::Int64Value>)

The recommended value for an INTEGER flag.

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

The name of the flag resource, following Google Cloud conventions, e.g.:
 * projects/{project}/locations/{location}/flags/{flag}
This field currently has no semantic meaning.

=item * C<< $msg->flag_name() >> / C<< $msg->flag_name($value) >>

Type: C<String>

The name of the database flag, e.g. "max_allowed_packets".
The is a possibly key for the Instance.database_flags map field.

=item * C<< $msg->value_type() >> / C<< $msg->value_type($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::SupportedDatabaseFlag::ValueType>)

=item * C<< $msg->accepts_multiple_values() >> / C<< $msg->accepts_multiple_values($value) >>

Type: C<Bool>

Whether the database flag accepts multiple values. If true,
a comma-separated list of stringified values may be specified.

=item * C<< $msg->supported_db_versions() >> / C<< $msg->supported_db_versions($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::DatabaseVersion>)

Major database engine versions for which this flag is supported.

=item * C<< $msg->requires_db_restart() >> / C<< $msg->requires_db_restart($value) >>

Type: C<Bool>

Whether setting or updating this flag on an Instance requires a database
restart. If a flag that requires database restart is set, the backend
will automatically restart the database (making sure to satisfy any
availability SLO's).

=item * C<< $msg->scope() >> / C<< $msg->scope($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::SupportedDatabaseFlag::Scope>)

The scope of the flag.

=back

=head3 Enum: SupportedDatabaseFlag::ValueType

=over 4

=item * C<VALUE_TYPE_UNSPECIFIED> => C<0>

=item * C<STRING> => C<1>

=item * C<INTEGER> => C<2>

=item * C<FLOAT> => C<3>

=item * C<NONE> => C<4>

=back

=head3 Enum: SupportedDatabaseFlag::Scope

=over 4

=item * C<SCOPE_UNSPECIFIED> => C<0>

=item * C<DATABASE> => C<1>

=item * C<CONNECTION_POOL> => C<2>

=back

=head2 Google::Cloud::Alloydb::V1::Resources::User

Message describing User object.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. Name of the resource in the form of
projects/{project}/locations/{location}/cluster/{cluster}/users/{user}.

=item * C<< $msg->password() >> / C<< $msg->password($value) >>

Type: C<String>

Input only. Password for the user.

=item * C<< $msg->database_roles() >> / C<< $msg->database_roles($value) >>

Type: C<String>

Optional. List of database roles this user has.
The database role strings are subject to the PostgreSQL naming conventions.

=item * C<< $msg->user_type() >> / C<< $msg->user_type($value) >>

Type: C<Enum> (L<Google::Cloud::Alloydb::V1::User::UserType>)

Optional. Type of this user.

=item * C<< $msg->keep_extra_roles() >> / C<< $msg->keep_extra_roles($value) >>

Type: C<Bool>

Input only. If the user already exists and it has additional roles, keep
them granted.

=back

=head3 Enum: User::UserType

=over 4

=item * C<USER_TYPE_UNSPECIFIED> => C<0>

=item * C<ALLOYDB_BUILT_IN> => C<1>

=item * C<ALLOYDB_IAM_USER> => C<2>

=back

=head2 Google::Cloud::Alloydb::V1::Resources::Database

Message describing Database object.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. Name of the resource in the form of
`projects/{project}/locations/{location}/clusters/{cluster}/databases/{database}`.

=item * C<< $msg->charset() >> / C<< $msg->charset($value) >>

Type: C<String>

Optional. Immutable. Charset for the database.
This field can contain any PostgreSQL supported charset name.
Example values include "UTF8", "SQL_ASCII", etc.

=item * C<< $msg->collation() >> / C<< $msg->collation($value) >>

Type: C<String>

Optional. Immutable. lc_collate for the database.
String sort order.
Example values include "C", "POSIX", etc.

=item * C<< $msg->character_type() >> / C<< $msg->character_type($value) >>

Type: C<String>

Optional. Immutable. lc_ctype for the database.
Character classification (What is a letter? The upper-case equivalent?).
Example values include "C", "POSIX", etc.

=item * C<< $msg->database_template() >> / C<< $msg->database_template($value) >>

Type: C<String>

Input only. Immutable. Template of the database to be used for creating a
new database.

=item * C<< $msg->is_template_database() >> / C<< $msg->is_template_database($value) >>

Type: C<Bool>

Optional. Whether the database is a template database.

=back

